-- Local-only, transactional payment authorization and accounting regression tests.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('83100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','billing-owner@test.local','',now(),'{}','{}',now(),now()),
('83100000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','billing-other@test.local','',now(),'{}','{}',now(),now()),
('83100000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','billing-staff@test.local','',now(),'{}','{}',now(),now());
insert into organizations(id,name,slug) values('83000000-0000-4000-8000-000000000001','Billing A','billing-test-a'),('83000000-0000-4000-8000-000000000002','Billing B','billing-test-b');
insert into organization_memberships(organization_id,user_id,role) values('83000000-0000-4000-8000-000000000001','83100000-0000-4000-8000-000000000001','owner'),('83000000-0000-4000-8000-000000000002','83100000-0000-4000-8000-000000000002','owner'),('83000000-0000-4000-8000-000000000001','83100000-0000-4000-8000-000000000003','manager');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"83100000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','month')->>'amountCentavos')::bigint,(select monthly_price_centavos from plans where id='starter'),'monthly price comes from catalog');
select is((quote_paymongo_plan('83000000-0000-4000-8000-000000000001','pro','year')->>'amountCentavos')::bigint,(select yearly_price_centavos from plans where id='pro'),'yearly price comes from catalog');
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000001','free','month')$$,'22023','Invalid plan','Free cannot be purchased');
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','week')$$,'22023','Invalid plan','invalid interval rejected');
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000002','starter','month')$$,'42501','Owner access required','cross-tenant quote denied');
select lives_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000001',false)$$,'owner begins checkout');
select is((select payment_description from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),(select 'TEST | NegOSu | Billing A | Starter | Monthly | New plan | Ref: '||id::text from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),'checkout description identifies business, plan, term, type and reference');
select throws_ok($$update billing_orders set payment_description='forged' where organization_id='83000000-0000-4000-8000-000000000001'$$,'42501',null,'owner cannot forge a payment description');
reset role;
update organizations set name=E'Renamed\nBilling | Branch' where id='83000000-0000-4000-8000-000000000001';
update billing_orders set payment_description='changed' where organization_id='83000000-0000-4000-8000-000000000001';
set local role authenticated;
select alike((begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000001',false)).payment_description,'TEST | NegOSu | Billing A | Starter | Monthly | New plan | Ref: %','rename and updates cannot change an existing checkout retry');
select lives_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000001',false)$$,'duplicate request reuses order');
select lives_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000002',false)$$,'another tab reuses open order');
select is((select count(*) from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),1::bigint,'only one open order created');
select throws_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','pro','month',gen_random_uuid(),false)$$,'P0001','Complete or cancel your open checkout first','conflicting checkout denied');
select throws_ok($$update billing_orders set amount_centavos=1 where organization_id='83000000-0000-4000-8000-000000000001'$$,'42501',null,'owner cannot change price');
select throws_ok($$select attach_paymongo_checkout((select id from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),'cs_A','https://checkout.paymongo.com/A')$$,'42501',null,'owner cannot attach arbitrary session');
select throws_ok($$select finish_paymongo_order(null,'cs_A','pay_A',1,'PHP',false,now(),'evt_A','hash')$$,'42501',null,'owner cannot activate access');
set local "request.jwt.claims"='{"sub":"83100000-0000-4000-8000-000000000002","role":"authenticated"}';
select is((select count(*) from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),0::bigint,'other owner cannot read orders');
set local "request.jwt.claims"='{"sub":"83100000-0000-4000-8000-000000000003","role":"authenticated"}';
select is((select count(*) from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),0::bigint,'manager cannot read billing orders');
select throws_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month',gen_random_uuid(),false)$$,'42501','Owner access required','manager cannot begin payment');
set local role anon;
select throws_ok($$select * from billing_orders$$,'42501',null,'anonymous orders denied');
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','month')$$,'42501',null,'anonymous checkout denied');
reset role;
create function pg_temp.settle(p_suffix text) returns text language sql as $$
select finish_paymongo_order(id,checkout_session_id,'pay_'||p_suffix,amount_centavos,currency,livemode,now(),'evt_'||p_suffix,'testhash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' order by created_at desc,id desc limit 1
$$;
select lives_ok($$select attach_paymongo_checkout((select id from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),'cs_A','https://checkout.paymongo.com/A')$$,'server attaches checkout');
select throws_ok($$select attach_paymongo_checkout((select id from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'),null,null)$$,'P0001','Invalid checkout','null checkout denied');
select throws_ok($$select finish_paymongo_order(id,'cs_A','pay_A',1,'PHP',false,now(),'evt_A','hash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'$$,'P0001','Payment verification mismatch','wrong amount denied');
select throws_ok($$select finish_paymongo_order(id,'cs_A','pay_A',amount_centavos,'USD',false,now(),'evt_A','hash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'$$,'P0001','Payment verification mismatch','wrong currency denied');
select throws_ok($$select finish_paymongo_order(id,'cs_A','pay_A',amount_centavos,'PHP',true,now(),'evt_A','hash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'$$,'P0001','Payment verification mismatch','wrong mode denied');
select throws_ok($$select finish_paymongo_order(id,'cs_other','pay_A',amount_centavos,'PHP',false,now(),'evt_A','hash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'$$,'P0001','Payment verification mismatch','wrong session denied');
select throws_ok($$select finish_paymongo_order(id,null,null,amount_centavos,'PHP',false,now(),'evt_A','hash') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001'$$,'P0001','Payment verification mismatch','null provider identifiers denied');
select is(pg_temp.settle('A'),'paid','verified payment activates');
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','starter','paid entitlements effective');
select is((select current_period_end from organization_subscriptions where organization_id='83000000-0000-4000-8000-000000000001'),now()+interval '1 month','monthly access exact');
select is(pg_temp.settle('A'),'paid','duplicate confirmation succeeds idempotently');
select is((select current_period_end from organization_subscriptions where organization_id='83000000-0000-4000-8000-000000000001'),now()+interval '1 month','retry does not extend access');
select is((select count(*) from audit_events where organization_id='83000000-0000-4000-8000-000000000001' and event_type='subscription.paymongo_paid'),1::bigint,'one payment audit event');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"83100000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','month')->>'kind','renewal','same plan renews');
select is((quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','month')->>'estimatedAccessEnd')::timestamptz,now()+interval '2 months','renewal extends existing access');
select is(quote_paymongo_plan('83000000-0000-4000-8000-000000000001','business','month')->>'kind','upgrade','higher plan upgrades');
select ok((quote_paymongo_plan('83000000-0000-4000-8000-000000000001','business','month')->>'creditCentavos')::bigint>0,'unused value preserved');
select ok((quote_paymongo_plan('83000000-0000-4000-8000-000000000001','business','month')->>'estimatedAccessEnd')::timestamptz>now()+interval '1 month','upgrade credit adds time');
select lives_ok($$select begin_paymongo_order('83000000-0000-4000-8000-000000000001','business','year','83200000-0000-4000-8000-000000000003',false)$$,'annual upgrade begins');
select alike((select payment_description from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' and status='creating'),'TEST | NegOSu | Renamed Billing Branch | Business | Yearly | Upgrade | Ref: %','new annual upgrade uses normalized current business name');
reset role;
select attach_paymongo_checkout(id,'cs_B','https://checkout.paymongo.com/B') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' and status='creating';
select is(finish_paymongo_order(id,'cs_B','pay_B',amount_centavos,'PHP',false,now(),'evt_B','hash'),'paid','annual upgrade activates') from billing_orders where checkout_session_id='cs_B';
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','business','upgrade replaces plan');
select ok((select current_period_end>now()+interval '1 year' from organization_subscriptions where organization_id='83000000-0000-4000-8000-000000000001'),'annual access includes unused value');
set local role authenticated;
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000001','starter','month')$$,'22023','Choose your current plan or a higher plan while access is active','mid-term downgrade denied');
select begin_paymongo_order('83000000-0000-4000-8000-000000000001','business','month','83200000-0000-4000-8000-000000000004',false);
reset role;
select attach_paymongo_checkout(id,'cs_C','https://checkout.paymongo.com/C') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' and status='creating';
create temp table previous_end as select current_period_end from organization_subscriptions where organization_id='83000000-0000-4000-8000-000000000001';
select is(finish_paymongo_order(id,'cs_C','pay_C',amount_centavos,'PHP',false,now(),'evt_C','hash'),'paid','renewal payment activates') from billing_orders where checkout_session_id='cs_C';
select is((select current_period_end from organization_subscriptions where organization_id='83000000-0000-4000-8000-000000000001'),(select current_period_end+interval '1 month' from previous_end),'renewal extends from existing expiry');
update organization_subscriptions set current_period_end=now()-interval '1 second' where organization_id='83000000-0000-4000-8000-000000000001';
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','free','expired prepaid access falls back without cron');
set local role authenticated;
select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000005',false);
reset role;
select attach_paymongo_checkout(id,'cs_D','https://checkout.paymongo.com/D') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' and status='creating';
update billing_orders set subscription_updated_at=now()-interval '1 minute' where checkout_session_id='cs_D';
select is(finish_paymongo_order(id,'cs_D','pay_D',amount_centavos,'PHP',false,now(),'evt_D','hash'),'review','stale subscription payment requires review') from billing_orders where checkout_session_id='cs_D';
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','free','stale payment cannot overwrite subscription');
set local role authenticated;
select begin_paymongo_order('83000000-0000-4000-8000-000000000001','starter','month','83200000-0000-4000-8000-000000000006',false);
reset role;
select attach_paymongo_checkout(id,'cs_E','https://checkout.paymongo.com/E') from billing_orders where organization_id='83000000-0000-4000-8000-000000000001' and status='creating';
update billing_orders set status='cancelled' where checkout_session_id='cs_E';
select is(finish_paymongo_order(id,'cs_E','pay_E',amount_centavos,'PHP',false,now(),'evt_E','hash'),'review','late cancelled checkout payment requires review') from billing_orders where checkout_session_id='cs_E';
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','free','late payment cannot unexpectedly replace plan');
update organization_subscriptions set provider='stripe',status='active',plan_id='starter' where organization_id='83000000-0000-4000-8000-000000000001';
select is(effective_entitlements('83000000-0000-4000-8000-000000000001')->>'planId','starter','legacy active subscriptions preserved');
set local role authenticated;
select throws_ok($$select quote_paymongo_plan('83000000-0000-4000-8000-000000000001','business','month')$$,'22023','Manage the existing subscription before switching payment providers','overlapping Stripe subscription denied');
reset role;
select * from finish();
rollback;
